(function(root){
const positive=n=>Number.isFinite(n)&&n>0;
const unit=s=>String(s||'').toLowerCase().replaceAll('²','2').replace(/[^\p{L}\p{N}]/gu,'');
const unitLabels={'м':'м.п.','пм':'м.п.','час':'ч','часа':'ч','часов':'ч','штук':'шт.','штука':'шт.','штуки':'шт.','мп':'м.п.','погм':'м.п.','м2':'м²','м3':'м³','см2':'см²','шт':'шт.','кг':'кг','л':'л','л(дм3)':'л','мл(см3)':'мл','компл':'компл.','уп':'уп.','упак':'уп.','рул':'рул.','н/ч':'н·ч','чел-ч':'чел·ч','чел/ч':'чел·ч','гиб':'гиб','отв':'отверстие','???':'Не указана','неуказана':'Не указана'};
function unitLabel(value){const text=String(value??'').trim(),key=text.normalize('NFKC').toLowerCase().replace(/[.\s]/g,'');return Object.hasOwn(unitLabels,key)?unitLabels[key]:text;}
function unitKey(value){const key=unitLabel(value).normalize('NFKC').toLowerCase().replace(/[.\s]/g,'');const aliases={мп:'м',погм:'м',пм:'м','н/ч':'нч','н·ч':'нч','чел·ч':'челч',час:'ч',часа:'ч',часов:'ч',штук:'шт',штука:'шт',штуки:'шт'};return Object.hasOwn(aliases,key)?aliases[key]:key;}
function sameUnit(a,b){const key=unitKey(a);return !!key&&!['???','неуказана'].includes(key)&&key===unitKey(b);}
function sheetSize(line,catalog){if(positive(line.sheetWidth)&&positive(line.sheetLength))return {width:line.sheetWidth,length:line.sheetLength,source:'Сохранённые размеры'};const c=catalog||line;if(!/лист|фанера/i.test(c.name||''))return null;const fmt=c.details?.['Длина / формат'];if(typeof fmt==='string'){const a=fmt.match(/\d+(?:[.,]\d+)?/g)?.map(n=>+n.replace(',','.'));if(a?.length===2&&a.every(positive))return {width:a[0],length:a[1],source:'Формат листа из прайса, м'};}const match=(c.name||'').match(/(\d+(?:[.,]\d+)?)\s*[хx×*]\s*(\d+(?:[.,]\d+)?)\s*[хx×*]\s*(\d+(?:[.,]\d+)?)/i);if(!match)return null;const a=match.slice(1).map(n=>+n.replace(',','.')).sort((a,b)=>a-b);return {width:a[1]/1000,length:a[2]/1000,source:'Два больших размера из наименования, мм; проверьте'};}
function convertSheet(line,width,length,target,whole){if(!positive(width)||!positive(length))throw Error('Укажите положительные ширину и длину листа в метрах');const from=unit(line.unit),to=unit(target);if(!['шт','лист','м2'].includes(from)||!['шт','м2'].includes(to))throw Error('Пересчёт поддерживает листы, штуки и м²');const area=width*length;if(!positive(area))throw Error('Некорректная площадь');const factor=from==='м2'?(to==='м2'?1:1/area):(to==='м2'?area:1);const out={...line,unit:to==='м2'?'м²':'шт.',sheetWidth:width,sheetLength:length,confirmed:false};for(const k of ['qty','pack'])out[k]=line[k]===null?null:line[k]*factor;for(const k of ['price','mass'])out[k]=line[k]===null?null:line[k]/factor;if(whole)out.pack=to==='м2'?area:1;if(line.estimate){out.estimate={...line.estimate,mass:out.mass};}out.source=line.source+' · пересчёт '+line.unit+' → '+out.unit+'; лист '+width+' × '+length+' м = '+area+' м²';return out;}
function estimate(line,mass,rate,grade,note){if(!positive(mass)||!positive(rate)||!String(grade).trim()||!String(note).trim())throw Error('Нужны масса единицы, ставка ₽/кг с НДС, вид стали и основание');const price=mass*rate;if(!positive(price))throw Error('Некорректная стоимость');return {...line,mass,price,confirmed:false,estimate:{mass,rate,grade:String(grade),note:String(note)},source:'Оценка по массе · '+grade+' · '+mass+' кг/'+line.unit+' × '+rate+' ₽/кг с НДС · '+note};}
function references(catalog,grade){return catalog.filter(c=>c.sheet==='Металлопрокат'&&/лист/i.test(c.name)&&positive(c.price)&&positive(c.mass)&&!c.needsReview&&(grade==='carbon'?c.supplier==='СтальГрад'&&c.category==='Лист г/к (горячекатаный)':grade==='09Г2С'?c.supplier==='СтальГрад'&&c.category==='Лист г/к 09Г2С':grade==='304'?/aisi\s*[- ]?304/i.test(c.name):grade==='316'?/aisi\s*[- ]?316/i.test(c.name):false)).map(c=>{const size=sheetSize(c,c),area=size?size.width*size.length:null,factor=unit(c.unit)==='м2'?area:1;return {id:c.id,name:c.name,price:c.price,mass:c.mass,unit:c.unit,sheetPrice:factor?c.price*factor:null,sheetMass:factor?c.mass*factor:null,rate:c.price/c.mass,date:c.date||'Дата не указана',source:c.purchaseSource||c.book+' · '+c.sheet+'!'+c.priceCell};}).sort((a,b)=>a.rate-b.rate);}
function stats(rows){const a=rows.map(c=>c.rate).filter(positive).sort((a,b)=>a-b),n=a.length;return {count:n,min:n?a[0]:null,max:n?a[n-1]:null,median:n?(a[Math.floor((n-1)/2)]+a[Math.floor(n/2)])/2:null};}
root.MaterialCore={sheetSize,convertSheet,estimate,references,stats,unitLabel,unitKey,sameUnit};if(typeof module!=='undefined')module.exports=root.MaterialCore;
})(typeof window!=='undefined'?window:globalThis);
